def save_as_callback(save_as: Optional[Tuple[ScanExport, Path]]) ->Tuple[
    Optional[str], Optional[Path]]:
    if save_as is None:
        return None, None

    export_format, export_path = save_as

    if export_format == ScanExport.SPDX:
        raise_if_not_spdx_extension_installed()

    return export_format.value, export_path

def output_callback(output: ScanOutput) ->str:
    return output.value
